trigger.sql:
DROP TRIGGER IF EXISTS trg_t10_after_insert ON dcops_t10_src;
CREATE OR REPLACE FUNCTION dcops_t10_fn() RETURNS trigger AS $$
BEGIN
  INSERT INTO dcops_t10_log (msg) VALUES ('inserted:' || NEW.id);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_t10_after_insert AFTER INSERT ON dcops_t10_src
FOR EACH ROW EXECUTE FUNCTION dcops_t10_fn()
